def rpm_tag(self, app):
    # SUSE-based distros (e.g., OpenSUSE) do not include a distro tag
    # in the RPM filename. Return an empty tag in that case.
    if app.target_vendor_base == SUSE:
        return ""
    elif app.target_vendor == "fedora":
        return f"fc{app.target_codename}"
    else:
        return f"el{app.target_codename}"

elif app.packaging_format == "rpm":
    # Some distros (e.g., OpenSUSE) omit the distro tag; avoid
    # emitting an extra dot when the tag is empty.
    tag = self.rpm_tag(app)
    tag_component = f".{tag}" if tag else ""
    return (
        f"{app.app_name}-{app.version}-{getattr(app, 'revision', 1)}"
        f"{tag_component}.{self.rpm_abi(app)}.rpm"
    )

